CREATE TABLE file_locations(org_id TEXT NOT NULL REFERENCES organizations(id), name TEXT NOT NULL, max_bytes INTEGER NOT NULL CHECK(max_bytes BETWEEN 1 AND 26214400), content_types_json TEXT NOT NULL DEFAULT '[]' CHECK(length(content_types_json) <= 2048), shared_read INTEGER NOT NULL DEFAULT 0 CHECK(shared_read IN (0, 1)), created_at TEXT NOT NULL, PRIMARY KEY(org_id, name));
CREATE TABLE files(org_id TEXT NOT NULL REFERENCES organizations(id), location TEXT NOT NULL, path TEXT NOT NULL, version INTEGER NOT NULL CHECK(version >= 0), size INTEGER NOT NULL CHECK(size >= 0), content_type TEXT NOT NULL CHECK(length(content_type) <= 128), sha256 TEXT NOT NULL CHECK(length(sha256) IN (0, 64)), status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending', 'ready')), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY(org_id, location, path));
CREATE INDEX files_location ON files(org_id, location, path);
CREATE TABLE file_policies(org_id TEXT NOT NULL REFERENCES organizations(id), location TEXT NOT NULL, action TEXT NOT NULL CHECK(action IN ('read', 'write', 'delete')), created_at TEXT NOT NULL, PRIMARY KEY(org_id, location, action));
CREATE TABLE file_capabilities(id TEXT PRIMARY KEY, org_id TEXT NOT NULL REFERENCES organizations(id), source_org_id TEXT NOT NULL, location TEXT NOT NULL, path TEXT NOT NULL, action TEXT NOT NULL CHECK(action IN ('upload', 'download')), staging_key TEXT, token_hash TEXT NOT NULL, expires_at TEXT NOT NULL, used_at TEXT, created_at TEXT NOT NULL);
CREATE INDEX file_capabilities_org ON file_capabilities(org_id, location, action);
